    perform jaspic_monitor.enqueue('batch-stopped:'||day_key,'分割配信停止','jaspic/dispatch',
     'DISPATCH_BATCH_STOPPED',p_now,'実行ID: '||r.id||
     E'\n送信済み（広島/滋賀）: '||h||'/'||s||
     E'\n未送信: '||(pending+failed)||' 件'||E'\n結果不明: '||(uncertain+other_count)||' 件');
